8: import type { GeoJSONPolygon, SatelliteScene } from '@tn-forest/shared/types';
9: 
10: /**
11:  * End-to-End Real Google Earth Engine Export -> Google Drive -> GeoTIFF Pipeline.
12:  *
13:  * Target Image: COPERNICUS/S2_SR_HARMONIZED/20200109T051201_20200109T051844_T43PHM
14:  * Target Zone: Sathiyar Dam / Reserve Forest
15:  */
16: async function runRealPipeline() {
17:   console.log('================================================================');
18:   console.log('🛰️ REAL GEE EXPORT ➔ GOOGLE DRIVE ➔ GEOTIFF PIPELINE');
19:   console.log('================================================================\n');
20: 
21:   // 1. Verify GEE Auth
22:   console.log('--- 1. VERIFY GOOGLE EARTH ENGINE AUTHENTICATION ---');
23:   const geeAuth = GeeAuthService.getInstance();
24:   const geeToken = await geeAuth.getAccessToken();
25:   if (!geeToken) {
26:     console.error('❌ GEE Authentication FAILED: No access token.');
27:     process.exit(1);
28:   }
29:   console.log('✅ [GEE] Authentication: SUCCESS\n');
30: 
31:   // 2. Verify Drive Auth
32:   console.log('--- 2. VERIFY INDEPENDENT GOOGLE DRIVE AUTHENTICATION ---');
33:   const driveService = new GoogleDriveService();
34:   const driveCheck = await driveService.checkDriveAccess();
35:   if (!driveCheck.authenticated || !driveCheck.apiAccess) {
36:     console.error('❌ [DRIVE] Authentication: FAILED');
37:     console.error(`Reason: ${driveCheck.error}\n`);
38:     console.error('Action Required:');
39:     console.error("  Please run 'gcloud auth login --enable-gdrive-access --update-adc' to grant Drive permissions to ADC.\n");
40:     process.exit(1);
41:   }
42:   console.log('✅ [DRIVE] Authentication: SUCCESS');
43:   console.log('✅ [DRIVE] Authenticated Drive access: SUCCESS');
44:   console.log(`✅ [DRIVE] Account: ${driveCheck.userEmail} (Files visible: ${driveCheck.filesCount ?? 0})\n`);
45: 
46:   // 3. Define target image & zone geometry
47:   const targetImageId = 'COPERNICUS/S2_SR_HARMONIZED/20200109T051201_20200109T051844_T43PHM';
48:   const sathiyarPolygon: GeoJSONPolygon = {
49:     type: 'Polygon',
50:     coordinates: [
51:       [
52:         [78.0747, 10.1182],
53:         [78.0867, 10.1118],
54:         [78.0939, 10.1196],
55:         [78.0890, 10.1235],
56:         [78.0797, 10.1228],
57:         [78.0747, 10.1182],
58:       ],
59:     ],
60:   };
61: 
62:   const scene: SatelliteScene = {
63:     satellite: 'Sentinel-2',
64:     sensorType: 'OPTICAL' as any,
65:     collection: 'COPERNICUS/S2_SR_HARMONIZED',
66:     imageId: targetImageId,
67:     acquisitionDate: new Date('2020-01-09T05:12:01.000Z'),
68:     cloudCover: 0.0,
69:     nativeResolution: 10,
70:     bands: ['B2', 'B3', 'B4', 'B8', 'B11', 'B12'],
71:     footprint: sathiyarPolygon,
72:     processingLevel: 'Level-2A',
73:     provider: 'GEE',
74:   };
75: 
76:   // 4. Request Real GEE Export to Google Drive
77:   console.log('--- 3. REQUEST REAL GEE EXPORT TO GOOGLE DRIVE ---');
78:   const exportService = new GeeExportService();
79:   const zoneCode = 'SATHIYAR';
80:   const jobId = `JOB-${Date.now().toString(36).toUpperCase()}`;
81: 
82:   console.log(`Target Image: ${targetImageId}`);
83:   console.log(`Zone Code:    ${zoneCode}`);
84:   console.log(`Scale:        10m`);
85:   console.log(`Bands:        B2, B3, B4, B8, B11, B12 (Homogeneous UInt16)`);
86:   console.log(`Destination:  Google Drive folder 'TN-Forest-Monitoring/GEE-Exports'`);
87: 
88:   const exportResult = await exportService.requestImageExport({
89:     scene,
90:     zoneCode,
91:     jobId,
92:     imageType: 'BASELINE',
93:     geometry: sathiyarPolygon,
94:     scaleMeters: 10,
95:   });
96: 
97:   console.log(`\n[GEE_EXPORT] Real Export Task Submitted!`);
98:   console.log(`  Task ID:        ${exportResult.taskId}`);
99:   console.log(`  Drive Filename: ${exportResult.driveFileName}`);
100:   console.log(`  Initial State:  ${exportResult.taskState}\n`);
101: 
102:   // 5. Poll Earth Engine Export Task
103:   console.log('--- 4. POLL EARTH ENGINE EXPORT OPERATION ---');
104:   const taskService = new GeeTaskService();
105:   const pollResult = await taskService.pollTaskCompletion(exportResult.taskId, {
106:     timeoutMs: 600000,
107:     pollIntervalMs: 10000,
108:   });
109: 
110:   console.log(`[GEE_TASK] Final State: ${pollResult.state}`);
111:   if (pollResult.state !== 'EXPORT_COMPLETED') {
112:     console.error(`❌ Export failed: ${pollResult.errorMessage || 'Unknown export error'}`);
113:     process.exit(1);
114:   }
115:   console.log('✅ [GEE_TASK] Earth Engine Export SUCCEEDED on Google servers!\n');
116: 
117:   // 6. Discover exported file on Google Drive
118:   console.log('--- 5. SEARCH GOOGLE DRIVE FOR EXPORTED GEOTIFF ---');
119:   const driveFile = await driveService.findExportedFile(exportResult.driveFileName);
120:   if (!driveFile || !driveFile.id) {
121:     console.error(`❌ [DRIVE] DRIVE_FILE_MISSING: File ${exportResult.driveFileName} not found in Google Drive.`);
122:     process.exit(1);
123:   }
124: 
125:   const driveFileId = driveFile.id;
126:   const driveFileName = driveFile.name || exportResult.driveFileName;
127:   const driveFileSizeBytes = Number(driveFile.size || 0);
128: 
129:   console.log(`✅ [DRIVE] Real File Verified!`);
130:   console.log(`  Drive File ID:   ${driveFileId}`);
131:   console.log(`  Drive File Name: ${driveFileName}`);
132:   console.log(`  File Size:       ${driveFileSizeBytes} bytes (${(driveFileSizeBytes / 1024).toFixed(2)} KB)\n`);
133: 
134:   if (driveFileSizeBytes <= 0) {
135:     console.error('❌ [DRIVE] File size is 0 bytes. Export is incomplete.');
136:     process.exit(1);
137:   }
138: 
139:   // 7. Stream Download GeoTIFF from Drive to local storage
140:   console.log('--- 6. STREAM DOWNLOAD GEOTIFF FROM GOOGLE DRIVE ---');
141:   const downloaded = await driveService.downloadGeoTiff({
142:     jobId,
143:     fileName: driveFileName,
144:     fileId: driveFileId,
145:   });
146: 
147:   console.log(`✅ [LOCAL] File downloaded to: ${downloaded.localFilePath}`);
148:   console.log(`✅ [LOCAL] Verified local size: ${downloaded.sizeBytes} bytes\n`);
149: 
150:   // 8. Validate GeoTIFF & Calculate Spectral Indices
151:   console.log('--- 7. RASTER VALIDATION & SPECTRAL INDICES ---');
152:   const fileBuffer = fs.readFileSync(downloaded.localFilePath);
153:   const parsed = await GeoTiffService.parseGeoTiff(fileBuffer);
154: 
155:   console.log(`  Raster Width:      ${parsed.metadata.width} px`);
156:   console.log(`  Raster Height:     ${parsed.metadata.height} px`);
157:   console.log(`  Total Pixels:      ${parsed.metadata.width * parsed.metadata.height}`);
158:   console.log(`  Band Count:        ${parsed.metadata.numBands}`);
159:   console.log(`  CRS:               ${parsed.metadata.crs || 'EPSG:4326'}`);
160: 
161:   const spectral = GeoTiffService.calculateSpectralIndices(parsed);
162:   console.log(`\n  Calculated Spectral Indices (from Real Pixel Reflectance):`);
163:   console.log(`    Mean NDVI: ${spectral.stats.ndviMean.toFixed(3)} (Vegetation health)`);
164:   console.log(`    Mean NDWI: ${spectral.stats.ndwiMean.toFixed(3)} (Water/Moisture)`);
165:   console.log(`    Mean NDBI: ${spectral.stats.nbrMean.toFixed(3)} (Built-up / Bare surface)`);
166: 
167:   console.log('\n================================================================');
168:   console.log('🎉 PIPELINE COMPLETE: REAL GEE ➔ DRIVE ➔ GEOTIFF SUCCESS!');
169:   console.log('================================================================');
170:   console.log(`Summary:`);
171:   console.log(`  Satellite Image: ${targetImageId}`);
172:   console.log(`  GEE Task ID:     ${exportResult.taskId}`);
173:   console.log(`  Drive File ID:   ${driveFileId}`);
174:   console.log(`  Drive File Name: ${driveFileName}`);
175:   console.log(`  File Size:       ${driveFileSizeBytes} bytes`);
176:   console.log(`  Raster:          ${parsed.metadata.width} x ${parsed.metadata.height} (${parsed.metadata.numBands} bands)`);
177:   console.log(`  NDVI:            ${spectral.stats.ndviMean.toFixed(3)}`);
178:   console.log('================================================================\n');
179: }
180: 
181: runRealPipeline().catch((err: unknown) => {
182:   const msg = err instanceof Error ? err.message : String(err);
183:   console.error('\n❌ Real Pipeline Failed:', msg);
184:   process.exit(1);
185: });
